// Fixture repositories of the test plan (C001-T-027): each helper builds the fixture in a temporary
// directory and returns its root and a cleanup function.
//   fx-empty          empty git repository
//   fx-bootstrap      this repository's .sdd/ with the bootstrap generator restored (hand-made workspace)
//   fx-brownfield-ts  small TypeScript service (src/billing, src/auth, src/checkout/payments.ts, tests)
//                     with a git history in which payments.ts churns
//   fx-large          generated by gen-large.mjs: 20 changes, 500 artifact files, 2,000 IDs
import { execFileSync } from "node:child_process";
import { cpSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { repoRoot } from "../helpers.ts";
import { generateLarge } from "./gen-large.mjs";

// Bundled tests run from build/, so paths start at the repository root, not at this file.
const REPO = repoRoot();
const HERE = join(REPO, "tests", "fixtures");

export interface Fixture {
  root: string;
  cleanup: () => void;
}

function temp(name: string): Fixture {
  const root = realpathSync.native(mkdtempSync(join(tmpdir(), `sdd-${name}-`)));
  return { root, cleanup: () => rmSync(root, { recursive: true, force: true }) };
}

function git(root: string, ...args: string[]): void {
  execFileSync("git", ["-c", "user.name=fixture", "-c", "user.email=fixture@example.invalid", "-c", "commit.gpgsign=false", ...args], { cwd: root, stdio: "ignore" });
}

export function fxEmpty(): Fixture {
  const fx = temp("fx-empty");
  git(fx.root, "init", "-q");
  return fx;
}

export function fxBootstrap(): Fixture {
  const fx = temp("fx-bootstrap");
  cpSync(join(REPO, ".sdd"), join(fx.root, ".sdd"), { recursive: true, filter: (src) => !src.includes(join(".sdd", "metrics")) });
  const sddMd = join(fx.root, ".sdd", "SDD.md");
  writeFileSync(sddMd, readFileSync(sddMd, "utf8").replace(/^generator: .*$/m, "generator: manual (bootstrap — Architect suite not yet built)"));
  return fx;
}

export function fxBrownfieldTs(): Fixture {
  const fx = temp("fx-brownfield-ts");
  cpSync(join(HERE, "fx-brownfield-ts"), fx.root, { recursive: true });
  git(fx.root, "init", "-q");
  git(fx.root, "add", ".");
  git(fx.root, "commit", "-q", "-m", "initial service");
  // Churn: payments.ts changes in several commits, the other files once.
  const payments = join(fx.root, "src", "checkout", "payments.ts");
  for (let i = 1; i <= 6; i++) {
    writeFileSync(payments, readFileSync(payments, "utf8") + `\n// revision ${i}: adjust capture rules\n`);
    git(fx.root, "commit", "-q", "-am", `payments: revision ${i}`);
  }
  return fx;
}

export function fxLarge(): Fixture {
  const fx = temp("fx-large");
  generateLarge(fx.root);
  return fx;
}
